from author import C,S,P,V
c=C('行列式与面积变化')
S(c,'行列式衡量带方向的面积变化',[
 P('把单位正方形跟着矩阵一起变形，它变成一个平行四边形。这个例子的两列分别是二和零、一和一，最后面积变成二。二阶行列式，就是左上乘右下，减去右上乘左下。几何上它表示带方向的面积倍率，所以绝对值给出面积放大多少倍，正负号还记录方向有没有翻转。',V('det',A=[[2,1],[0,1]]),[r'\det A=ad-bc',r'\det A=2'],['绝对值表示面积倍率','符号还记录方向翻转'],10),
 P('现在把两个方向压到同一条直线上，原来的面被压扁，行列式就变成零。这意味着不同输入可能被压到同一个输出，信息丢失，不能再唯一恢复。交换两个基准方向时，面积大小不变，方向却翻过来，所以行列式变号。高阶行列式可对应体积或更高维的体积倍率，但并不是所有矩阵都有行列式，本课只对方阵使用它。',V('det',A=[[1,2],[1,2]]),[r'\det A=0\ \Longrightarrow\ \text{压缩了维度}'],['压扁时面积倍率为零','行列式针对方阵'],10)],['1.1-行列式概念'])
S(c,'逆序数与一般定义',[
 P('高阶行列式的定义，要用到排列。把一到 n 每个数恰好出现一次，按某种次序排起来，就是一个排列。从左往右看，某个较大的数排在较小的数前面，这一对就构成逆序。画面里的三、一、二，有三在一前面和三在二前面两对逆序，所以逆序数为二，是偶排列。我们数的是成对关系，不是移动了几次。',V('permutation',values=[3,1,2]),[r'\tau(312)=2',r'(-1)^2=1'],['每个逆序比较一对位置','逆序数偶数为偶排列'],10),
 P('一般 n 阶行列式的定义，是每行选一个元素、每列也恰好选一个，把所选元素相乘，再按对应列排列的奇偶性决定正负，最后全部相加。一共有 n 的阶乘种选法。二阶时正好只剩两项，就回到刚才的公式。本例六种选择中，非零项是三和四，相加得到七。这个定义帮助理解符号和性质，大矩阵通常不逐项硬列。',V('permutation',values=[1,3,2],matrix=[[1,2,0],[0,3,1],[2,0,1]]),[r'\det A=\sum_{\sigma}(-1)^{\tau(\sigma)}',r'\qquad\cdot a_{1\sigma(1)}\cdots a_{n\sigma(n)}'],['每行每列各选一个元素','排列奇偶决定这一项的符号'],12)],['1.1-逆序数与奇偶','1.1-n阶定义与定义计算'])
S(c,'行列式的基本性质',[
 P('先看交换两行。用两行组成的两个方向交换位置后，行列式变成相反数。因此两行完全相同时，交换以后表格没变、行列式却要变号，只能是零。两行成比例也会使它为零。转置则不改变行列式，行与列在这些性质里具有对应地位，所以同样的叙述也可以用于列。',V('det',A=[[2,1],[0,1]],phase='rowswap'),[r'\det(A^T)=\det A',r'R_i\leftrightarrow R_j:\ D\to-D'],['交换两行，行列式变号','相同或成比例的两行为零'],10),
 P('把一行乘 k，行列式也乘 k；把整个 n 阶矩阵乘 k，则每一行都被乘了一遍，所以倍率是 k 的 n 次方。若某一行是一对行向量的和，可以把行列式拆成两个相加，其他行保持不变。这里的可加性是针对某一行，不代表两个矩阵相加后的行列式，总等于它们行列式的和。这个限制一定要一起记住。',V('det',A=[[1,0],[0,1]],phase='rowscale',factor=2),[r'\det(kA)=k^n\det A',r'\det(A+B)\ne\det A+\det B\ \text{一般}'],['一行数乘只贡献一个因子','某一行可拆，不是整矩阵随意拆'],10)],['1.2-转置不变','1.2-交换与相同行推论','1.2-行因子与比例行推论','1.2-按一行可加'])
S(c,'加一行的倍数为什么不改变结果',[
 P('现在把第二行加上第一行的两倍。平行四边形变得更斜，但底边和对应的高所决定的面积没有变化，行列式保持不变。代数上，把新行拆开，会出现原来的行列式，加上一个含比例行的行列式，后一项为零。这条性质是把一个地方消成零、又不改变行列式的重要工具。',V('det',A=[[1,1],[0,2]],phase='rowadd',factor=2),[r'R_2\leftarrow R_2+2R_1',r'D\ \text{不变}'],['一行加另一行的倍数，行列式不变','新增加的那一项含比例行'],10),
 P('注意，加一行的倍数、交换两行、把一行数乘，它们对行列式的影响不同。消元时不能统称为初等变换，所以行列式不变。可以边计算边在旁边记账：交换一次变号，某行数乘要记录因子，加倍数不用改。养成记账的习惯，后面用阶梯形计算行列式时，就不会把一个正确的消元过程配上错误的最后答案。',V('elimination',states=[[[1,1],[0,2]],[[1,1],[2,4]]],labels=['原矩阵','R₂ ← R₂ + 2R₁']),[r'\text{交换：变号}',r'\text{一行数乘：乘因子}',r'\text{加另一行倍数：不变}'],['三种变换的影响分别记录','不能把所有初等变换说成保值'],6)],['1.2-倍加不变'])
S(c,'余子式与按行展开',[
 P('求三阶行列式时，可以先固定一个位置，删掉它所在的行和列，留下的较小行列式叫余子式。再乘上由行列编号之和决定的正负号，得到代数余子式。正负号从左上角的正号开始，像棋盘一样交替。余子式是剩下的行列式，代数余子式还包含这个位置的符号，两者不能混写。',V('cofactor',A=[[1,2,0],[0,3,1],[2,0,1]],cell=[0,1]),[r'C_{ij}=(-1)^{i+j}M_{ij}'],['删去所在行与列得到余子式','再乘位置符号得到代数余子式'],10),
 P('沿任意一行展开，就把这一行的每个元素乘上它自己的代数余子式，再相加。图上选择含零较多的一行，可以减少计算。本例沿第一行，得到三加四，结果是七。相应地也能沿一列展开。还有一个常用推论：一行的元素若配上另一行对应位置的代数余子式，相加得到零，而不是原行列式。',V('cofactor',A=[[1,2,0],[0,3,1],[2,0,1]],cell=[0,0],phase='expand'),[r'D=\sum_j a_{ij}C_{ij}',r'\sum_j a_{ij}C_{kj}=0\quad(i\ne k)',r'D=1\cdot3+2\cdot2=7'],['展开可选任意一行或一列','另一行配对的和为零'],12)],['1.3-余子式与代数余子式','1.3-展开定理及推论'])
S(c,'消元与范德蒙行列式',[
 P('先用一行加另一行的倍数，把主对角线下面逐步消成零。得到三角形以后，行列式就是主对角线元素的乘积。这里每一步只用了不改变行列式的倍加，所以最终直接相乘即可。若中途交换过行，或者把某一行除以一个数，就必须把对应的变号或因子补回去。看清变换种类，比只记住最后乘对角线更重要。',V('elimination',states=[[[1,2,1],[2,5,3],[1,0,2]],[[1,2,1],[0,1,1],[0,-2,1]],[[1,2,1],[0,1,1],[0,0,3]]],labels=['原矩阵','消去第一列下方','消去第二列下方']),[r'D=1\cdot1\cdot3=3'],['倍加消成三角形','对角线相乘前先核对变换记录'],12),
 P('有些行列式有特殊结构，不需要硬算。范德蒙行列式每一行从一开始，后面依次是某个数的一次、二次，直到更高次幂。按图里的排列，它等于所有后一个数减前一个数的差相乘。取一、二、四时，得到一乘三乘二，等于六。如果两个数相同，会出现相同的行，差的乘积里也出现零，两种解释正好一致。',V('matrix',A=[[1,1,1],[1,2,4],[1,4,16]],operation='vandermonde'),[r'D=\prod_{i<j}(x_j-x_i)',r'D=(2-1)(4-1)(4-2)=6'],['注意幂的排列方式与差的顺序','两个参数相同，结果为零'],8)],['1.4-消元展开与规律','1.4-范德蒙'])
S(c,'克莱默法则的适用条件',[
 P('对未知数个数和方程个数相同的方程组，如果系数行列式不为零，就有唯一解。克莱默法则把第 j 个未知数写成一个比值：分母是系数行列式，分子把第 j 列换成常数列以后再算。这里方程是 x 加 y 等于三、x 减 y 等于一，计算后得到 x 等于二、y 等于一。',V('cramer',A=[[1,1],[1,-1]],b=[3,1]),[r'x_j=\frac{D_j}{D},\quad D\ne0',r'x=2,\quad y=1'],['替换的是列，不是行','分母非零才可使用这个比值'],10),
 P('若分母为零，不能继续相除，也不能立刻断言无解，可能无解，也可能有无穷多解，要用秩进一步判断。对齐次方程组，也就是右边全为零的情形，方阵行列式非零时只有零解；为零时存在非零解。这里仍有方阵这个条件，不能给任意长方形系数表硬套一个行列式。下一章再把非零行列式与逆矩阵连接起来。',V('nullspace',mode='homogeneous-criterion'),[r'A\mathbf{x}=0:\ D\ne0\iff\text{仅零解}',r'D=0\iff\text{存在非零解}'],['D 为零时，克莱默比值失效','齐次方阵条件下可判断非零解'],8)],['1.5-克莱默法则','1.5-齐次方阵零解与非零解'])
S(c,'练习：面积倍率是多少',[
 P('矩阵的两列分别是二和零、一和三。它把单位正方形变成什么样，面积是原来的多少倍？如果只交换两列，行列式和面积各会怎样变化？这里有两个问题：一个问带符号的行列式，一个问没有正负号的面积。请先算二乘三减零，再考虑交换方向的影响。',V('det',A=[[2,1],[0,3]],phase='question'),[r'A=\left[\,(2,0)^T\ (1,3)^T\,\right]',r'\det A\ ?'],['区分行列式与面积','交换两列会改变什么'],0)],['1-练习'],kind='question',answer='行列式6，面积扩大6倍；交换两列后行列式-6，面积仍扩大6倍。')
S(c,'答案：符号和大小分开看',[
 P('原来的行列式是六，因此面积放大六倍。交换两列以后，行列式变成负六，但绝对值仍是六，面积倍率没有改变。方向翻转，不等于面积变成了负数。图中顶点顺序翻了过来，而平行四边形占据的大小相同。把数值里的符号和几何大小分开，是理解行列式很关键的一步。',V('det',A=[[2,1],[0,3]],phase='swap'),[r'D=6\longrightarrow-6',r'|D|=6'],['交换列只改变符号','实际面积取绝对值'],10),
 P('到这里，行列式有了三种用途：描述面积倍率，借助性质简化计算，并判断方阵是否丢失方向。一般定义、余子式展开和消元不是互相冲突的算法，而是从同一个数出发选择不同计算路径。具体题目先观察结构，再决定怎么计算。接下来关心更实际的问题：变换以后，能不能找到一套操作，把输入完整恢复。',V('transform',A=[[2,1],[0,3]]),[r'\det A\ne0\quad\text{方向没有被压扁}'],['先观察结构，再选择算法','下一步：恢复输入'],8)],['1-练习答案'])

c=C('初等变换与逆矩阵')
S(c,'逆矩阵把变换撤回来',[
 P('先把网格拉伸并错切，再用另一张矩阵把它送回原处。如果前后两种顺序相乘都得到单位矩阵，后面这张矩阵就叫原矩阵的逆，记作 A 的负一次方。这里的负一次方表示撤销变换，不是每个元素分别取倒数。只有同阶方阵且行列式不为零时，逆矩阵才存在，而且一旦存在就是唯一的。',V('inverse',A=[[2,1],[0,1]]),[r'A^{-1}A=AA^{-1}=I',r'A\text{可逆}\iff\det A\ne0'],['逆矩阵撤销整体变换','不是逐元素取倒数'],12),
 P('二阶时有一个方便公式：交换主对角线上两个数，另外两个数变号，再整体除以行列式。一般情形要把各位置代数余子式排成表，再转置，得到伴随矩阵；它与原矩阵相乘等于行列式乘单位矩阵。因此可逆时，伴随矩阵除以行列式就是逆矩阵。这个方法适合解释公式，小规模能用，大规模通常用消元。',V('matrix',A=[[2,1],[0,1]],operation='adjugate'),[r'A\,\operatorname{adj}(A)=(\det A)I',r'A^{-1}=\frac{\operatorname{adj}(A)}{\det A}',r'A^{-1}=\frac1{ad-bc}\,[\,d,-b;-c,a\,]'],['伴随矩阵要对代数余子式表转置','可逆时才允许除以行列式'],8)],['2.3-定义与可逆条件','2.3-伴随矩阵与二阶求逆'])
S(c,'三种初等变换与初等矩阵',[
 P('消元只需要三种基本操作：交换两行，把一行乘非零数，以及把一行加上另一行的某个倍数。非零这个条件不能漏，否则会直接丢掉信息。这三种操作都能用反向操作撤回来。对列也有相应的三类变换。这里讨论保持问题之间的可恢复关系，而不是说每种操作都让行列式保持相同。',V('elimination',states=[[[1,2],[3,4]],[[3,4],[1,2]],[[6,8],[1,2]],[[6,8],[7,10]]],labels=['原矩阵','交换两行','第一行乘二','第二行加第一行']),[r'R_i\leftrightarrow R_j',r'R_i\leftarrow kR_i\ (k\ne0)',r'R_i\leftarrow R_i+kR_j'],['三种操作都能撤回','行数乘的系数必须非零'],14),
 P('把单位矩阵做一次这样的操作，得到的矩阵叫初等矩阵。对 A 做行变换，等价于在左边乘相应初等矩阵；做列变换，则在右边乘。左右位置来自矩阵乘法的规则，不是随便约定的装饰。知道这个对应关系，就能把一串消元步骤写成一串可逆矩阵的乘积，也解释了为什么这些变换不会改变矩阵的秩。',V('multiply',A=[[1,0],[-2,1]],B=[[1,2],[2,5]]),[r'\text{行变换：}EA',r'\text{列变换：}AE'],['单位矩阵一次初等变换得到 E','左乘对应行，右乘对应列'],10)],['2.4-三种变换与初等矩阵','2.4-对应定理'])
S(c,'把左边化成单位矩阵来求逆',[
 P('把 A 与单位矩阵并排写在一起，对整个长表同步做行变换。我们要把左边逐步化成单位矩阵。这里先用第二行减去第一行的两倍，把左下角消成零；再用第一行减去第二行，消掉左上方多余的项。一定是整行一起操作，右边的数字也必须同步改变，不能只修改左半张表。',V('elimination',states=[[[1,1,1,0],[2,3,0,1]],[[1,1,1,0],[0,1,-2,1]],[[1,0,3,-1],[0,1,-2,1]]],labels=['[A | I]','R₂ ← R₂ − 2R₁','R₁ ← R₁ − R₂'],split=2),[r'[A\mid I]\longrightarrow[I\mid A^{-1}]'],['左右同步做行变换','目标是左半部分变为 I'],14),
 P('左边成为单位矩阵时，右边就是逆矩阵，本例是三、负一、负二、一组成的二阶矩阵。为什么成立？同一串左乘操作把 A 送成 I，它们的总作用就是 A 的逆；作用在右边的 I 上，自然留下这张逆矩阵。如果左边始终出现缺少主元的零行，不能化成单位矩阵，就说明 A 不可逆，不能强行宣布右半部分是答案。',V('inverse',A=[[1,1],[2,3]]),[r'A^{-1}=[\,3,-1;-2,1\,]',r'AA^{-1}=I'],['右半部分是逆矩阵','最后可乘回去检查'],10)],['2.4-初等变换求逆'])
S(c,'可逆矩阵的运算顺序',[
 P('先穿上外套，再背上书包，撤销时通常先放下书包、再脱外套。矩阵乘积求逆也要反序。如果 A 和 B 都可逆，A B 的逆等于 B 的逆乘 A 的逆。转置和求逆则可以交换先后，得到转置后的逆等于逆矩阵的转置。这里各张矩阵必须有合适尺寸且确实可逆，不能在条件不满足时套写符号。',V('inverse',A=[[2,1],[0,1]],phase='composition'),[r'(AB)^{-1}=B^{-1}A^{-1}',r'(A^T)^{-1}=(A^{-1})^T'],['撤销复合操作时顺序反过来','转置与求逆可以交换'],12),
 P('逆矩阵的行列式是原行列式的倒数，这也符合面积先放大、再缩小回来的图像。可逆矩阵还保持秩，因此左边或右边乘一个可逆矩阵，不会改变独立信息的数量。以后碰到矩阵等价、相似和合同，都要留意左右究竟乘了什么。它们外形相近，但要求和保持的性质不同，不能把所有关系都叫作同一件事。',V('transform',A=[[0.5,-0.5],[0,1]]),[r'\det(A^{-1})=\frac1{\det A}',r'r(PAQ)=r(A)\quad(P,Q\text{可逆})'],['面积倍率互为倒数','可逆乘法不改变秩'],10)],['2.3-可逆矩阵性质'])
S(c,'练习：能否逐元素取倒数',[
 P('看矩阵 A，主对角线上是一，右上角也是一，左下角是零。有人认为，把每个非零元素取倒数、零保留不动，就得到逆矩阵。这个方法对不对？你可以不用猜，直接考虑候选矩阵和 A 相乘是否等于单位矩阵。逆矩阵的定义，比记忆某一种外形更可靠。请独立思考四秒。',V('matrix',A=[[1,1],[0,1]],operation='question'),[r'A=[\,1,1;0,1\,]',r'A^{-1}\ ?'],['逆必须撤销整体变换','用乘积是否等于 I 检验'],0)],['2.3-练习'],kind='question',answer='不对。A的逆为[[1,-1],[0,1]]，而不是原矩阵本身。')
S(c,'答案：用反向错切撤销',[
 P('不对。原矩阵让网格向右错切，撤销它应该向左错切，所以右上角要变成负一。把二者相乘，主对角线为一，右上角的一与负一抵消，才得到单位矩阵。若照逐元素取倒数的想法，候选仍是原矩阵，连做两次会继续错切，右上角变成二，显然没有恢复原状。',V('inverse',A=[[1,1],[0,1]]),[r'A^{-1}=[\,1,-1;0,1\,]',r'A^2=[\,1,2;0,1\,]\ne I'],['逆矩阵是反向错切','乘回 I 才是有效检验'],12),
 P('求逆不一定每次都用同一种工具。二阶可以用公式，小规模可以用伴随矩阵，系统计算常用增广表消元。无论选哪种，最后的定义都一样。还要检查行列式是否为零，不能为了写出一个逆，就对零进行除法。下一章把独立方向的数量正式称为秩，用它统一解释压扁、不可逆和方程组自由程度。',V('matrix',A=[[1,-1],[0,1]],highlight='diagonal'),[r'\det A\ne0\iff A^{-1}\text{存在}'],['先确认存在，再选择算法','下一步：独立方向有多少'],0)],['2.3-练习答案'])
